//! Provider adapter layer for the Tracelane gateway.
//!
//! Each sub-module translates the universal `ChatRequest` format into the
//! provider-specific wire format, handles SSE streaming, and emits `ProviderEvent`
//! items that the gateway aggregates into a response stream.
//!
//! **Providers are a DATA FILE, not code.** `crates/gateway/providers.tsv` holds
//! every OpenAI-compatible provider — id, label, base URL, env vars, model
//! prefixes — and is generated by `scripts/ci/build-provider-catalog.py`. Six
//! native adapters (Anthropic, Google AI Studio, Google Vertex, AWS Bedrock,
//! Azure OpenAI, Cohere) remain as Rust modules because their wire format
//! genuinely differs.
//!
//! Adding a provider is one row and zero Rust. It used to be ~15 lines across
//! six files plus ~10 count and claim edits across six more, and the counts in
//! this header were themselves CI-enforced string literals — was a
//! doc-comment miscount that leaked to public marketing. There is no count in
//! this comment any more, deliberately: the number is `catalog::providers()`
//! plus six, and a comment nobody checks is a claim waiting to rot.

// Prefix data is shared by the canonical match and the settings inventory.
const ANTHROPIC_PREFIXES: &[&str] = &["claude", "anthropic/"];
const VERTEX_PREFIXES: &[&str] = &["vertex/"];
const GOOGLE_PREFIXES: &[&str] = &["gemini", "google/"];
const BEDROCK_PREFIXES: &[&str] = &["bedrock/"];
const AZURE_PREFIXES: &[&str] = &["azure/"];
// D9/OG-06: `rerank-` routes Cohere's rerank models (`rerank-v3.5`, …) to its native adapter.
const COHERE_PREFIXES: &[&str] = &["command", "cohere/", "rerank-"];
pub const NATIVE_PREFIXES: &[(&str, &[&str])] = &[
    ("anthropic", ANTHROPIC_PREFIXES),
    ("vertex", VERTEX_PREFIXES),
    ("google", GOOGLE_PREFIXES),
    ("bedrock", BEDROCK_PREFIXES),
    ("azure", AZURE_PREFIXES),
    ("cohere", COHERE_PREFIXES),
];

